      ('Facelift'::text, 'Hatchback 5-door'::text, 'DKZA'::text, 150::integer, 'DQ381'::text, null::text),
      ('Facelift'::text, 'Estate'::text, 'DKZA'::text, 150::integer, 'DQ381'::text, null::text),
      ('Facelift'::text, 'Hatchback 5-door'::text, 'DNPA'::text, 195::integer, 'DQ381'::text, null::text),
      ('Facelift'::text, 'Estate'::text, 'DNPA'::text, 195::integer, 'DQ381'::text, null::text),
      ('Facelift'::text, 'Estate'::text, 'DNFB'::text, 245::integer, 'DQ381'::text, 'haldex_gen6'::text),
      ('Pre-facelift'::text, 'Hatchback 5-door'::text, 'DADA'::text, 110::integer, 'MQ281'::text, null::text),
      ('Pre-facelift'::text, 'Estate'::text, 'DADA'::text, 110::integer, 'MQ281'::text, null::text),
      ('Pre-facelift'::text, 'Hatchback 5-door'::text, 'DADA'::text, 110::integer, 'DQ200'::text, null::text),
      ('Pre-facelift'::text, 'Estate'::text, 'DADA'::text, 110::integer, 'DQ200'::text, null::text),
      ('Pre-facelift'::text, 'Hatchback 5-door'::text, 'DKZA'::text, 140::integer, 'DQ381'::text, null::text),
      ('Pre-facelift'::text, 'Estate'::text, 'DKZA'::text, 140::integer, 'DQ381'::text, null::text),
      ('Pre-facelift'::text, 'Hatchback 5-door'::text, 'DNPA'::text, 180::integer, 'DQ381'::text, null::text),
      ('Pre-facelift'::text, 'Estate'::text, 'DNPA'::text, 180::integer, 'DQ381'::text, null::text),
      ('Pre-facelift'::text, 'Hatchback 5-door'::text, 'DNFC'::text, 221::integer, 'DQ381'::text, null::text),
      ('Pre-facelift'::text, 'Estate'::text, 'DNFB'::text, 228::integer, 'DQ381'::text, 'haldex_gen6'::text)
  )
insert into catalog_vehicle_configurations (phase_id, body_type_id, engine_id, unit_id, drivetrain_id)
select p.id, b.id, e.id, u.id, d.id
from configs c
join phase_lookup p on p.phase_label = c.phase_label
join body_lookup b on b.name = c.body_name
join engine_lookup e on e.code = c.engine_code and e.power_kw = c.engine_power_kw
join unit_lookup u on u.code = c.unit_code or c.unit_code = any(u.alt_codes)
left join dt_lookup d on d.code = c.dt_code
on conflict (
  phase_id, body_type_id, engine_id, unit_id,
  coalesce(drivetrain_id, '00000000-0000-0000-0000-000000000000'::uuid)
) do nothing;

